<?php $title='Automações';require __DIR__.'/_top.php';?><div class="page-heading"><div><p class="eyebrow">Jornada da reserva</p><h1>Automações</h1></div></div><section class="admin-panel"><h2>17 jornadas mínimas</h2><?php foreach($rules as $rule):?><div class="block-row"><div><strong><?= e($rule['name']) ?></strong><small><?= e($rule['trigger_event']) ?> · <?= e($rule['schedule_anchor']) ?> <?= (int)$rule['offset_minutes'] ?> min · <?= $rule['ativo']?'ativa':'pausada' ?></small></div><?php if(can('automation.manage')):?><form method="post" action="<?= e(base_url('admin/operacoes/automation-toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="rule_id" value="<?= (int)$rule['id'] ?>"><button class="admin-secondary"><?= $rule['ativo']?'Pausar':'Ativar' ?></button></form><?php endif;?></div><?php endforeach;?></section><section class="admin-panel"><h2>Execuções recentes</h2><?php if(!$runs):?><p class="empty-state">Nenhuma execução.</p><?php endif;?><?php foreach($runs as $run):?><div class="block-row"><strong><?= e($run['codigo']) ?> · <?= e($run['rule_name']) ?></strong><small><?= e($run['status']) ?> · programada <?= e($run['scheduled_at']) ?><?= $run['error_message']?' · '.e($run['error_message']):'' ?></small></div><?php endforeach;?></section><?php require __DIR__.'/_bottom.php';?>
